css_diff:
--- callback02 identical HEAD CSS
+++ current course/web/course.css
@@ -15,6 +15,14 @@
 .md-typeset .output-label { margin: 0; color: var(--md-default-fg-color--light); font-size: .65rem; }
 .md-typeset .output img { max-width: 100%; height: auto; }
 .md-typeset mjx-container[display="true"] { max-width: 100%; overflow-x: auto; overflow-y: hidden; }
+/* 手機頁內目錄放進固定頁首，避免收合時遮住正文行尾。 */
+@media screen and (max-width: 59.984375em) {
+  .md-sidebar--secondary { top: .3rem; bottom: auto; right: 5rem; z-index: 5; }
+  .md-sidebar--secondary .md-sidebar__inner { top: 2.7rem; bottom: auto; right: -4.2rem; }
+  .md-header__title { margin-right: 2.4rem; }
+  #__search:checked ~ .md-container .md-sidebar--secondary,
+  #__drawer:checked ~ .md-container .md-sidebar--secondary { visibility: hidden; }
+}
 @media (prefers-reduced-motion: reduce) {
   .md-typeset *, .md-typeset *::before, .md-typeset *::after { animation: none !important; transition: none !important; }
 }
